/* CDIDummy (no DWARF record; file-local to this unit: vtable 0x471bb0, RTTI 0x44ce88): the DI
 * of the AI-map hits, a CDI whose tests never hit. Its vtable keeps CDI's Allocate, Free and
 * Read and adds LoadTipAndTail at +0x20 (no caller: the vtable is reached only through `di`).
 * audit-unmarked-a2: the port had no such class (`di` was a CDIPoly, whose GetIntersect /
 * GetAltitude would run polygon tests on no points) */
class CDIDummy : public zdb::CDI
{
public:
	virtual ~CDIDummy();
	virtual bool GetIntersect(zdb::DiIntersect *);
	virtual bool GetAltitude(zdb::DiIntersect *);
	virtual void LoadTipAndTail(zdb::DiIntersect *);
};

/* GetIntersect__8CDIDummyFPQ23zdb11DiIntersect 0x1f24f0: no hit */
bool CDIDummy::GetIntersect(zdb::DiIntersect *)
{
	return false;
}

/* GetAltitude__8CDIDummyFPQ23zdb11DiIntersect 0x1f2500: no hit */
bool CDIDummy::GetAltitude(zdb::DiIntersect *)
{
	return false;
}

/* LoadTipAndTail__8CDIDummyFPQ23zdb11DiIntersect 0x1f2510: empty */
void CDIDummy::LoadTipAndTail(zdb::DiIntersect *)
{
}

/* __dt__8CDIDummyFv 0x1f2520 (registered by __sinit for `di`, so at exit only): its vtable,
 * ~CDI, delete when asked */
CDIDummy::~CDIDummy()
{
}

/* @socom-skeleton stub di */
/* 36 bytes: the DI record of ftsGetAltitudeApprox's AI-map hits (only its material bits are
 * written). __sinit_fts_main.cpp 0x46aa50 constructs it: CDI(), then CDIDummy's vtable (was a
 * CDIPoly, with a comment that the ELF never constructs it) */
static CDIDummy di;

/* @socom-skeleton stub hit */
static zdb::IntersectStruct hit; /* 32 bytes: ftsGetAltitudeApprox's AI-map hit */

/* @socom-skeleton stub ftsGetAltitudeApprox__FPC6CPnt3Dfb */
zdb::IntersectStruct * ftsGetAltitudeApprox(const CPnt3D *position, float offset, bool skip_aimap)
{
	/* 0x1f20f0: unless skipped, the AI map's altitude under the point: the map holding the point
	 * lifted by the offset, its cell (not one with a bad altitude or soil 10), the cell under the
	 * point in that map, its flat altitude (bbox min y + the 10-bit altitude in 1/1024 of the map's
	 * height) or bilinear altitude; with the cell's extra data present, the result is the file's
	 * hit record (normal unit_y, the extra data's byte 3 as the DI's material). Otherwise, or with
	 * "compare" set, the world's GetAltitude. The statics start 1 and 0 (first-call init guards
	 * in the ELF). */
	/* @socom-skeleton stub useaimap$2199 */
	static unsigned char useaimap = 1;
	/* @socom-skeleton stub compare$2202 */
	static unsigned char compare = 0;
	bool found = false;

	if (useaimap && !skip_aimap)
	{
		CPnt3D probe(position->x, position->y + offset, position->z);
		CAiMapLoc loc;

		if (AiMaps.GetLocation(&probe, loc))
		{
			CAiMap *map = AiMaps.GetMapByIndex(loc.m_mapid);
			CAiCell *cell = map->GetCell(loc);
			f32 altitude = 0.0f;

			/* ELF 0x1f224c: the cell is not NULL-tested (AiMaps.GetLocation put loc on the map,
			 * so GetCell answers a cell or the dummy one) */
			if (!cell->m_badalt && cell->m_soil != 10)
			{
				CAiMapLoc local;
				bool have = false;

				if (map->GetLocation(position, local))
				{
					CAiCell *under = map->GetCell(local);

					if (under != NULL && under->m_bilinear)
					{
						/* 0x1f2360: blended from the cell and its neighbours */
						have = map->GetBilinearAltitude(local, position, &altitude);
					}
					else if (under != NULL)
					{
						altitude = map->m_bbox.m_min.y + (map->m_bbox.m_max.y - map->m_bbox.m_min.y) * 0.00097656297f * (f32)under->m_altitude;
						have = true;
					}
				}

				if (have)
				{
					if (char *extra = map->GetMapEx(loc))
					{
						hit.m_node = NULL;
						hit.m_norm = CPnt3D::unit_y;
						hit.m_pos.x = position->x;
						hit.m_pos.y = altitude;
						hit.m_pos.z = position->z;
						hit.m_poly = &di;
						di.m_material = (u8)extra[3];
						found = true;
					}
				}
			}
		}
	}

	if (!found || compare)
		return zdb::CWorld::m_world->GetAltitude(position, offset);

	return &hit;
}
